package org.springframework.samples.petclinic.acceptance;

import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Test;

import tools.jackson.databind.node.ObjectNode;

/** postcode: a supplied postcode must lie within the range of the owner's city region. */
class PostcodeRegionAcceptanceTest extends AcceptanceBase {

	@Test
	void storesPostcodeWithinCityRegion() throws Exception {
		ObjectNode o = ownerNode();
		o.put("city", "Melbourne");
		o.put("postcode", "3050");
		int id = createOwnerOk(o);
		getOwner(id).andExpect(jsonPath("$.postcode").value("3050"));
	}

	@Test
	void rejectsPostcodeOutsideCityRegion() throws Exception {
		ObjectNode o = ownerNode();
		o.put("city", "Sydney");
		o.put("postcode", "3000");
		createOwner(o).andExpect(status().isBadRequest())
			.andExpect(jsonPath("$.schemaValidationErrors[0].field").value("postcode"));
	}
}
